SHA = "4b2cb36934c035c2ba81fc2997dc51d826d76365aa363da8b0b7fac4b5e5dade"

def fin(msg):
    raise SystemExit(msg)

if not os.path.exists('www/index.html'):
    try:
        os.chdir('/workspaces/PORTAL_CONDUCTOR/portal')
    except OSError:
        pass
p = 'www/index.html'
if not os.path.exists(p):
    fin('ERROR: no encuentro www/index.html (ejecuta el parche desde la carpeta portal). No se ha cambiado nada.')
try:
    js = zlib.decompress(base64.b64decode(P_JS)).decode('utf-8')
    css = zlib.decompress(base64.b64decode(P_CSS)).decode('utf-8')
    ok_sum = hashlib.sha256((css + '\n' + js).encode('utf-8')).hexdigest() == SHA
except Exception:
    ok_sum = False
if not ok_sum:
    fin('ERROR: el parche esta danado (la suma de control no coincide). Vuelve a subir v316.py. No se ha cambiado nada.')

with open(p, encoding='utf-8', newline='') as f:
    orig = f.read()
s = orig
# quita una version anterior de este mismo parche (asi se puede volver a pasar sin duplicar nada)
s = re.sub(r'<!--v316-begin-->.*?<!--v316-end-->\n?', '', s, flags=re.S)
s = re.sub(r'[ ]*<!--v316-menu-->.*?<!--v316-menu-end-->\n?', '', s, flags=re.S)

AYUDA = '<button class="drawer-item" onclick="closeSideMenu();renderHelp()"><span class="di">❓</span><span><b>Ayuda</b><small>Ayuda para conductores y contacto</small></span><span class="arr">›</span></button>'
STYLE315 = '<style id="v315-style">'
need = [
    (AYUDA, 'la entrada «Ayuda» del menu de las tres rayitas'),
    (STYLE315, 'el bloque de estilos v315-style'),
    ('function backToGeneralMenu()', 'la funcion backToGeneralMenu'),
    ('function renderNotifications()', 'la funcion renderNotifications'),
    ('id="v315-script"', 'el bloque v315-script'),
]
for a, name in need:
    n = s.count(a)
    if n != 1:
        fin('ERROR: ' + name + (' no esta' if n == 0 else ' esta repetido (' + str(n) + ' veces)') + '. No se ha cambiado nada.')

MENU = ('\n    <!--v316-menu--><button class="drawer-item" onclick="closeSideMenu();renderMadridHoy()"><span class="di">\U0001F326️</span><span><b>Madrid hoy</b>'
        '<small>Tiempo y eventos de Madrid</small></span><span class="arr">›</span></button><!--v316-menu-end-->')
BLOCK = '<!--v316-begin-->\n<style id="v316-style">\n' + css + '</style>\n<script id="v316-info">\n' + js + '</script>\n<!--v316-end-->\n'
s = s.replace(AYUDA, AYUDA + MENU, 1)
s = s.replace(STYLE315, BLOCK + STYLE315, 1)
if s.count('id="v316-info"') != 1 or s.count('<!--v316-menu-->') != 1:
    fin('ERROR interno: la insercion no ha quedado bien. No se ha cambiado nada.')
if s == orig:
    print('v3.16 ya aplicado: no hay nada que cambiar.')
    raise SystemExit(0)
fd, tmp = tempfile.mkstemp(dir='www', suffix='.tmp')
os.close(fd)
with open(tmp, 'w', encoding='utf-8', newline='') as f:
    f.write(s)
os.replace(tmp, p)
print('pagina: actualizada')
print('v3.16 aplicado: pantalla «Madrid hoy» (tiempo + eventos) en el menu de las tres rayitas, debajo de Ayuda')
